          "text": "填装漏斗应证明它如何减少洒粉；密封圈应明确对应杯体版本；滤网应说明拆装与清洁方式。耐用与易用也要分开：一个器具能使用很久，不代表买家愿意持续清洗。经营上可以分别观察首次使用成功、重复购买替换件与退货原因，让配件开发围绕真实摩擦，而不是不断增加没有用处的套装件数。",
