          "text": "纸基可堆肥、铝材回收、可重复填充，以及无传统萃取外壳的咖啡片，处理的是不同问题。可填充让用户承担装粉与清洗；可堆肥改变末端处理条件；新咖啡片系统还可能改变机器入口。于是行业竞争从每杯风味与方便，延伸到材料、回收网络和家庭工作量。哪种路线更适合一个用户，需要把这些条件一起比较。",
