          "title": "德国：量价背离之外，是整豆结构在变化",
          "text": "德国咖啡协会披露，2025 年烘焙咖啡销量约 45.6 万吨，同比 −1.5%；销售额却增至 89.8 亿欧元，同比 ＋23.5%。整豆销量为 19.38 万吨，协会称十年累计增长约 130%，而研磨咖啡同期下降约 38%。这说明“整体喝得多”之外，购买形态也在变。它为整豆业务提供具体研究方向，但原文没有给出可填充胶囊的市场规模。",
